17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
37	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
65	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        validateRequiredFields(ownerFieldsDto);
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
120	        rejectDuplicateTelephone(telephone);
121	        owner.setTelephone(telephone);
122	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    /**
135	     * Builds the next customer code, formatted {@code <LAST3>-<NNNN>} where LAST3 is the
136	     * upper-cased first three letters of the owner's last name and NNNN is a global 4-digit
137	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
138	     *
139	     * @param lastName the owner's last name
140	     * @return the assigned customer code
141	     */
142	    private String nextCustomerCode(String lastName) {
143	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
144	        int sequence = this.clinicService.findAllOwners().size() + 1;
145	        return String.format("%s-%04d", last3, sequence);
146	    }
147	
148	    /**
149	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
150	     * offending field so the client learns about all of them at once.
151	     *
152	     * @param ownerFieldsDto the submitted owner fields
153	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
154	     *                                     missing or blank
155	     */
156	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
157	        List<String> errors = new ArrayList<>();
158	        if (isBlank(ownerFieldsDto.getFirstName())) {
159	            errors.add("firstName");
160	        }
161	        if (isBlank(ownerFieldsDto.getLastName())) {
162	            errors.add("lastName");
163	        }
164	        if (isBlank(ownerFieldsDto.getAddress())) {
165	            errors.add("address");
166	        }
167	        if (isBlank(ownerFieldsDto.getCity())) {
168	            errors.add("city");
169	        }
170	        if (isBlank(ownerFieldsDto.getTelephone())) {
171	            errors.add("telephone");
172	        }
173	        if (!errors.isEmpty()) {
174	            throw new MissingOwnerFieldsException(errors);
175	        }
176	    }
177	
178	    private boolean isBlank(String value) {
179	        return value == null || value.isBlank();
180	    }
181	
182	    /**
183	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
184	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
185	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
186	     * followed by 8 to 15 digits.
187	     *
188	     * @param telephone the raw telephone value as submitted
189	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
190	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
191	     */
192	    private String normalizeTelephone(String telephone) {
193	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
194	        String nationalSignificantNumber;
195	        if (cleaned.startsWith("+")) {
196	            nationalSignificantNumber = cleaned.substring(1);
197	        } else {
198	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
199	            nationalSignificantNumber = "61" + national;
200	        }
201	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
202	            throw new InvalidTelephoneException(telephone);
203	        }
204	        return "+" + nationalSignificantNumber;
205	    }
206	
207	    /**
208	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
209	     * value is treated as absent and returns {@code null}); when present the value must be a
210	     * syntactically valid address, and is stored and returned lower-cased.
211	     *
212	     * @param email the raw email value as submitted, may be {@code null}
213	     * @return the lower-cased email, or {@code null} when none was supplied
214	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
215	     */
216	    private String normalizeEmail(String email) {
217	        if (email == null || email.isBlank()) {
218	            return null;
219	        }
220	        String normalized = email.trim().toLowerCase();
221	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
222	            throw new InvalidEmailException(email);
223	        }
224	        return normalized;
225	    }
226	
227	    /**
228	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
229	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
230	     * comparison, so numbers that differ only in formatting still count as duplicates.
231	     *
232	     * @param e164Telephone the E.164 telephone of the owner being created
233	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
234	     */
235	    private void rejectDuplicateTelephone(String e164Telephone) {
236	        boolean inUse = this.clinicService.findAllOwners().stream()
237	            .map(Owner::getTelephone)
238	            .filter(existing -> existing != null)
239	            .map(this::toComparableTelephone)
240	            .filter(existing -> existing != null)
241	            .anyMatch(e164Telephone::equals);
242	        if (inUse) {
243	            throw new DuplicateTelephoneException(e164Telephone);
244	        }
245	    }
246	
247	    /**
248	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
249	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
250	     * than aborting the whole create.
251	     */
252	    private String toComparableTelephone(String telephone) {
253	        try {
254	            return normalizeTelephone(telephone);
255	        } catch (InvalidTelephoneException ex) {
256	            return null;
257	        }
258	    }
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
263	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
264	        if (currentOwner == null) {
265	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	        }
267	        currentOwner.setAddress(ownerFieldsDto.getAddress());
268	        currentOwner.setCity(ownerFieldsDto.getCity());
269	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
270	        currentOwner.setLastName(ownerFieldsDto.getLastName());
271	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
272	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
273	        this.clinicService.saveOwner(currentOwner);
274	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
275	    }
276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Transactional
279	    @Override
280	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
281	        Owner owner = this.clinicService.findOwnerById(ownerId);
282	        if (owner == null) {
283	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
284	        }
285	        this.clinicService.deleteOwner(owner);
286	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
287	    }
288	
289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
290	    @Override
291	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
292	        Owner owner = this.clinicService.findOwnerById(ownerId);
293	        if (owner == null) {
294	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	        }
296	        HttpHeaders headers = new HttpHeaders();
297	        Pet pet = petMapper.toPet(petFieldsDto);
298	        owner.setId(ownerId);
299	        pet.setOwner(owner);
300	        pet.getType().setName(null);
301	        this.clinicService.savePet(pet);
302	        PetDto petDto = petMapper.toPetDto(pet);
303	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
304	            .buildAndExpand(pet.getId()).toUri());
305	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
311	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
312	        if (currentOwner != null) {
313	            Pet currentPet = this.clinicService.findPetById(petId);
314	            if (currentPet != null) {
315	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
316	                currentPet.setName(petFieldsDto.getName());
317	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
318	                this.clinicService.savePet(currentPet);
319	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
320	            }
321	        }
322	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
323	    }
324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
328	        HttpHeaders headers = new HttpHeaders();
329	        Visit visit = visitMapper.toVisit(visitFieldsDto);
330	        Pet pet = new Pet();
331	        pet.setId(petId);
332	        visit.setPet(pet);
333	        this.clinicService.saveVisit(visit);
334	        VisitDto visitDto = visitMapper.toVisitDto(visit);
335	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
336	            .buildAndExpand(visit.getId()).toUri());
337	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
338	    }
339	
340	
341	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
342	    @Override
343	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
344	        Owner owner = this.clinicService.findOwnerById(ownerId);
345	        if (owner != null) {
346	            Pet pet = owner.getPet(petId);
347	            if (pet != null) {
348	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
349	            }
350	        }
351	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	    }
353	}
