package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when an owner being created has the same lastName and address (compared
 * case-insensitively with collapsed whitespace) as an existing owner, and the request did not
 * opt in with {@code sharesHousehold=true}. Carries the offending last name and address so they
 * can be reported to the client.
 */
public class DuplicateHouseholdException extends RuntimeException {

    private final String lastName;

    private final String address;

    public DuplicateHouseholdException(String lastName, String address) {
        super("An owner with the same last name and address already exists: " + lastName + ", " + address);
        this.lastName = lastName;
        this.address = address;
    }

    public String getLastName() {
        return this.lastName;
    }

    public String getAddress() {
        return this.address;
    }
}

